  const liveUrl=`${window.location.origin}/site/${site?.slug||""}`;
  const copyLiveUrl=async()=>{try{await navigator.clipboard.writeText(liveUrl);setNotice("Live URL copied to clipboard");setTimeout(()=>setNotice(""),3000)}catch{setNotice(liveUrl);setTimeout(()=>setNotice(""),5000)}};
  const upload = async (file, productIndex = null) => { const form = new FormData(); form.append("image", file); const { data } = await axios.post("/api/v1/builder/upload", form); if(productIndex!==null){const products=[...(currentBlock.products||[])];products[productIndex]={...products[productIndex],image:data.url};patchBlock({products});}else patchBlock({ image: data.url }); };
  const editorSite=site?{...site,onThemeChange:fields=>patchSite({theme:{...site.theme,...fields}}),onSiteNameChange:name=>patchSite({name}),onEditBlock:(blockId,fields)=>updateBlocks(activePage.blocks.map(b=>b.id===blockId?{...b,...fields}:b)),onMoveBlock:moveBlock}:site;
